import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const html = fs.readFileSync('card-playground.html', 'utf8');
assert.match(html, /<title>Profile card playground<\/title>/i);
assert.match(html, /name=["']viewport["']/i);
assert.doesNotMatch(html, /<(?:script|link|img)\b[^>]*(?:src|href)\s*=\s*["'](?:https?:|\/\/)/i);
for (const id of ['radius', 'padding', 'shadow', 'preview', 'prompt', 'copy']) {
  assert.match(html, new RegExp('id=["\']' + id + '["\']', 'i'), 'Missing ' + id);
}
for (const name of ['Balanced', 'Compact', 'Soft']) assert.ok(html.includes(name), 'Missing preset ' + name);
const scripts = [...html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi)];
assert.equal(scripts.length, 1, 'Use one inline script');
assert.doesNotMatch(scripts[0][1], /src\s*=/i);
const source = scripts[0][2];
assert.match(source, /addEventListener\s*\(\s*['"]input['"]/);
assert.match(source, /addEventListener\s*\(\s*['"]click['"]/);
assert.match(source, /clipboard\.writeText/);
assert.match(source, /Copied!/);
assert.match(source, /cardModel\s*\(\s*state\s*\)/);
assert.match(source, /function\s+updateAll\s*\(/);
const sandbox = vm.createContext({});
vm.runInContext(source + ';globalThis.probeAPI = {cardModel, PRESETS, DEFAULTS};', sandbox, {timeout: 1000});
const api = sandbox.probeAPI;
const expected = {Balanced:{radius:12,padding:20,shadow:false},Compact:{radius:4,padding:12,shadow:false},Soft:{radius:20,padding:28,shadow:true}};
assert.deepEqual(JSON.parse(JSON.stringify(api.PRESETS)), expected);
assert.deepEqual(JSON.parse(JSON.stringify(api.DEFAULTS)), expected.Balanced);
const inputs = [expected.Balanced,expected.Compact,expected.Soft,{radius:0,padding:8,shadow:true}];
for (const input of inputs) {
  const output = api.cardModel(input);
  assert.equal(output.style.borderRadius, input.radius + 'px');
  assert.equal(output.style.padding, input.padding + 'px');
  if (input.shadow) assert.notEqual(output.style.boxShadow, 'none');
  else assert.equal(output.style.boxShadow, 'none');
  assert.match(output.prompt, /profile card/i);
  if (input.radius !== 12) assert.ok(output.prompt.includes(input.radius + 'px'));
  if (input.padding !== 20) assert.ok(output.prompt.includes(input.padding + 'px'));
  if (input.shadow) assert.match(output.prompt, /shadow/i);
}
const defaults = api.cardModel(expected.Balanced).prompt;
assert.ok(!defaults.includes('12px') && !defaults.includes('20px'), 'Default values must not clutter the prompt');
const report = {cases:4,presets:3,styleParity:true,nonDefaultPrompts:true,inlineOnly:true};
fs.writeFileSync('playground-verification.json', JSON.stringify(report) + '\n');
console.log('Card playground: 4 actual model-function cases; 3 presets; inline control bindings verified');

